import { Component, OnDestroy, OnInit } from "@angular/core";
import {
  combineLatest,
  debounceTime,
  filter,
  forkJoin,
  map,
  Observable,
  Subject,
  Subscription,
  switchMap,
} from "rxjs";
import { MockDataService } from "./mock-data.service";

@Component({
  selector: "app-root",
  templateUrl: "./app.component.html",
  styleUrls: ["./app.component.scss"],
})
export class AppComponent implements OnInit, OnDestroy {
  searchTermByCharacters = new Subject<string>();
  charactersResults$!: Observable<any>;
  planetAndCharactersResults$!: Observable<any>;
  isLoading: boolean = false;
  subscriptions: Subscription[] = [];

  constructor(private mockDataService: MockDataService) {}

  ngOnInit(): void {
    this.initLoadingState();
    this.initCharacterEvents();
  }

  changeCharactersInput(element: any): void {
    const inputValue: string = element.target.value.trim();
    this.searchTermByCharacters.next(inputValue);
  }
  initCharacterEvents(): void {
    this.charactersResults$ = this.searchTermByCharacters.pipe(
      filter((term) => term.length >= 3), // Only 3+ chars
      debounceTime(300), // Wait for pause
      switchMap((term) => this.mockDataService.getCharacters(term)) // Call API
    );
  }

  loadCharactersAndPlanet(): void {
    this.planetAndCharactersResults$ = forkJoin([
      this.mockDataService.getCharacters(),
      this.mockDataService.getPlatents(),
    ]).pipe(
      map(([characters, planets]) => {
        // Combine the names into one array
        const characterNames = characters.map((c: any) => c.name);
        const planetNames = planets.map((p: any) => p.name);
        return [...characterNames, ...planetNames];
      })
    );
  }

  initLoadingState(): void {
    const sub = combineLatest([
      this.mockDataService.getCharactersLoader(),
      this.mockDataService.getPlanetLoader(),
    ]).subscribe((loaderStates: boolean[]) => {
      this.isLoading = this.areAllValuesTrue(loaderStates);
    });

    this.subscriptions.push(sub);
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((sub) => sub.unsubscribe());
  }

  areAllValuesTrue(elements: boolean[]): boolean {
    return elements.every((el) => el);
  }
}
<loader [isLoading]="isLoading"></loader>
<div class="content">
    <div class="logo">
        <img
                src="https://brandpalettes.com/wp-content/uploads/2021/06/star-wars-color-codes.svg"
                width="100"
        />
    </div>

    <input
            (keyup)="changeCharactersInput($event)"
            [placeholder]="'Search by characters'"
    />
    <ng-container *ngIf="charactersResults$ | async as results">
        <div *ngIf="results.length > 0; else noResults">
            <div *ngFor="let item of results">
                {{ item.name }}
            </div>
        </div>
        <ng-template #noResults> No results </ng-template>
    </ng-container>

    <button (click)="loadCharactersAndPlanet()">Load Characters And Planets</button>
    <ng-container *ngIf="planetAndCharactersResults$ | async as results">
        <div *ngIf="results.length > 0; else noResults">
            <div *ngFor="let item of results">
                {{ item.name }}
            </div>
        </div>
        <ng-template #noResults> No results </ng-template>
    </ng-container>
</div>
